const user = $input.first().json;
const deptRaw = (user.department || '').trim().toLowerCase();
const areaFrontend = ($('Webhook Login').first().json.body.area || '')
  .replace(/^Acceso a\s*/i, '')
  .trim();

const deptMap = {
  'soporte': 'Soporte',
  'marketing': 'Marketing',
  'contabilidad': 'Contabilidad',
  'comercial': 'Comercial',
  'sales operations': 'Comercial',
  'sales operatins': 'Comercial',
  'sales operations ': 'Comercial',
  'sales operations management': 'Comercial',
  'operaciones': 'Operaciones',
  'calidad': 'Calidad',
  'ti': 'TI',
  'desarrollo': 'TI',
  'gerencia': 'Gerencia',
  'd. organizacional': 'Gerencia',
  'analítica de datos': 'Analítica',
  'analitica de datos': 'Analítica',
  'co': 'Comercial',
};

const areaMapeada = deptMap[deptRaw] || null;
const tieneAcceso = areaMapeada === areaFrontend;

return [{
  json: {
    email: user.mail,
    nombre: user.displayName,
    cargo: user.jobTitle,
    departamento: user.department,
    areaMapeada,
    areaFrontend,
    tieneAcceso,
    accountEnabled: user.accountEnabled
  }
}];

const redirects = {
  'Soporte':      'https://soporte.mobilvendor.com',
  'Marketing':    'https://marketing.mobilvendor.com',
  'Contabilidad': 'https://contabilidad.mobilvendor.com',
  'Comercial':    'https://comercial.mobilvendor.com',
  'Operaciones':  'https://operaciones.mobilvendor.com',
  'Calidad':      'https://calidad.mobilvendor.com',
  'TI':           'https://ti.mobilvendor.com',
  'Gerencia':     'https://gerencia.mobilvendor.com',
  'Analitica':    'https://analitica.mobilvendor.com',
};

const area = $json.areaMapeada;
const url = redirects[area] || 'https://intranet.mobilvendor.com';

return [{
  json: {
    status: 'ok',
    redirect: url,
    nombre: $json.nombre,
    cargo: $json.cargo,
    area: area
  }
}];

const webhookJson = $("Webhook Chat A1").item.json;

const bodyRaw = webhookJson.body || webhookJson || {};
const body = typeof bodyRaw === 'string' ? JSON.parse(bodyRaw) : bodyRaw;

const message = body.message || body.question || '';
const files = Array.isArray(body.files) ? body.files : [];
const history = Array.isArray(body.history) ? body.history : [];

const model = body.model || 'gpt-4.1';
const temperature = body.temperature ?? 0.2;
const maxOutputTokens = body.max_output_tokens || 4000;
const user = body.user || 'Usuario';
const org = body.organization || 'MobilVendor';

const sessionId =
  body.sessionId ||
  body.session_id ||
  body.user_id ||
  body.userId ||
  user;

let lastResponseId = null;
const rows = $input.all();
if (rows.length > 0 && rows[0].json && rows[0].json.last_response_id) {
  lastResponseId = String(rows[0].json.last_response_id).trim() || null;
}

function toDataUrl(file) {
  if (!file || !file.data) return null;
  if (String(file.data).startsWith('data:')) return file.data;
  const mime = file.type || file.mimeType || 'application/octet-stream';
  const base64 = String(file.data).includes(',')
    ? String(file.data).split(',')[1]
    : String(file.data);
  return `data:${mime};base64,${base64}`;
}

const systemPrompt = `
Eres el asistente interno de ${org}.
Responde en español profesional, claro y útil.
Puedes responder preguntas normales y analizar archivos adjuntos.
Cuando el usuario adjunte archivos, basa tu respuesta en esos archivos.
Si el archivo no puede leerse o no contiene la información solicitada, dilo claramente.
No inventes datos de documentos internos.
Usuario: ${user}
SessionId: ${sessionId}
Fecha local: ${new Date().toLocaleString('es-EC', { timeZone: 'America/Guayaquil' })}
`.trim();

const inputMsgs = [
  {
    role: 'system',
    content: [{ type: 'input_text', text: systemPrompt }]
  }
];

for (const h of history.slice(-8)) {
  if (!h.role || !h.content) continue;
  inputMsgs.push({
    role: h.role === 'assistant' ? 'assistant' : 'user',
    content: [{
      type: h.role === 'assistant' ? 'output_text' : 'input_text',
      text: String(h.content)
    }]
  });
}

const userContent = [];

for (const file of files) {
  const fileName = file.name || file.fileName || 'archivo';
  const mime = file.type || file.mimeType || 'application/octet-stream';
  const ext = fileName.split('.').pop().toLowerCase();
  const dataUrl = toDataUrl(file);
  if (!dataUrl) continue;
  if (mime.startsWith('image/') || ['png','jpg','jpeg','webp','gif'].includes(ext)) {
    userContent.push({ type: 'input_image', image_url: dataUrl });
  } else {
    userContent.push({ type: 'input_file', filename: fileName, file_data: dataUrl });
  }
}

userContent.push({
  type: 'input_text',
  text: message || 'Analiza los archivos adjuntos y dame un resumen.'
});

const openaiPayload = {
  model,
  temperature,
  max_output_tokens: maxOutputTokens,
  input: [
    ...inputMsgs,
    { role: 'user', content: userContent }
  ],
  metadata: { sessionId, user, org }
};

if (lastResponseId) {
  openaiPayload.previous_response_id = lastResponseId;
}

return [{
  json: {
    message,
    model,
    temperature,
    max_output_tokens: maxOutputTokens,
    user,
    org,
    sessionId,
    last_response_id: lastResponseId,
    files_count: files.length,
    openaiPayload
  }
}];

const resp = $input.first().json;

let text = '';

try {
  if (resp.output_text) {
    text = resp.output_text;
  }
  if (!text && Array.isArray(resp.output)) {
    for (const item of resp.output) {
      if (!item.content) continue;
      for (const c of item.content) {
        if (c.type === 'output_text' && c.text) text += c.text;
      }
    }
  }
  if (!text && resp.choices?.[0]?.message?.content) {
    text = resp.choices[0].message.content;
  }
  if (!text) text = JSON.stringify(resp, null, 2);
} catch (e) {
  text = 'Error interpretando la respuesta de OpenAI: ' + e.message;
}

const sessionId = resp.metadata?.sessionId || null;
const user = resp.metadata?.user || null;
const org = resp.metadata?.org || null;

return [{
  json: {
    response: text,
    model: resp.model || 'gpt-4.1',
    response_id: resp.id || null,
    tokens_used: resp.usage?.total_tokens || null,
    status: 'success',
    timestamp: new Date().toISOString(),
    sessionId,
    user,
    org
  }
}];

